<?php
if($id&&$name==='clients'){
 echo '<section class="panel"><h2>Placement requests</h2><p><a class="button" href="'.e(url('admin/record.php?module=requests&client_id='.$id)).'">Create request for this client</a></p><ul>';foreach(query('SELECT id,role,status FROM client_requests WHERE client_id=? ORDER BY id DESC LIMIT 100',[$id])->fetchAll() as $r)echo '<li>'.record_link('requests',(int)$r['id']).' · '.e($r['role']).' · '.e($r['status']).'</li>';echo '</ul></section>';
}
if($id&&$name==='requests'){
 echo '<section class="panel"><h2>Candidates for consideration</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Candidate</th><th>Status</th><th>Placement</th></tr></thead><tbody>';
 foreach(query('SELECT m.*,c.full_name FROM client_candidate_matches m JOIN candidates c ON c.id=m.candidate_id WHERE client_request_id=? ORDER BY m.id DESC LIMIT 100',[$id])->fetchAll() as $match){echo '<tr><td>'.record_link('candidates',(int)$match['candidate_id'],$match['full_name']).'</td><td><form method="post" class="inline-form">'.csrf_input().'<input type="hidden" name="action" value="match_status"><input type="hidden" name="match_id" value="'.(int)$match['id'].'"><input type="hidden" name="version" value="'.(int)$match['version'].'">';select_field('match_status','Consideration status',match_statuses(),$match['status']);echo '<button>Update</button></form></td><td><a href="'.e(url('admin/record.php?module=placements&client_request_id='.$id.'&candidate_id='.$match['candidate_id'])).'">Create placement</a></td></tr>';}
 echo '</tbody></table></div>';$q=is_string($_GET['candidate_q']??null)?substr($_GET['candidate_q'],0,160):'';$rfilter=is_string($_GET['candidate_role']??null)?$_GET['candidate_role']:'';
 echo '<h3>Add candidate for consideration</h3><form method="get" class="filters"><input type="hidden" name="module" value="requests"><input type="hidden" name="id" value="'.$id.'">';input_field('candidate_q','Name, area or availability',$q);select_field('candidate_role','Role',array_merge([''],role_names()),$rfilter);echo '<button>Find candidates</button></form><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Candidate</th><th>Area / availability</th><th>Action</th></tr></thead><tbody>';
 $params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];$filter='';if($rfilter!==''){$filter=' AND EXISTS(SELECT 1 FROM candidate_roles r WHERE r.candidate_id=c.id AND r.role=?)';$params[]=$rfilter;}
 foreach(query("SELECT c.* FROM candidates c WHERE c.status IN ('Available','Being Considered','Placement Pending') AND (c.full_name LIKE ? OR c.area LIKE ? OR c.availability LIKE ?)".$filter.' ORDER BY c.full_name LIMIT 20',$params)->fetchAll() as $c)echo '<tr><td>'.record_link('candidates',(int)$c['id'],$c['full_name']).'</td><td>'.e($c['area'].' / '.$c['availability']).'</td><td><form method="post">'.csrf_input().'<input type="hidden" name="action" value="match"><input type="hidden" name="candidate_id" value="'.(int)$c['id'].'"><button>Add</button></form></td></tr>';
 echo '</tbody></table></div><p class="muted">Up to 20 matches. Refine the search if needed. Selection remains a staff decision.</p></section>';
}
if($id&&$name==='candidates'){
 echo '<section class="panel"><h2>Placement history</h2><ul>';foreach(query('SELECT id,status FROM placements WHERE candidate_id=? ORDER BY id DESC LIMIT 100',[$id])->fetchAll() as $p)echo '<li>'.record_link('placements',(int)$p['id']).' · '.e($p['status']).'</li>';echo '</ul>';if($user['role']==='super_admin')echo '<p><a href="'.e(url('admin/documents.php?candidate_id='.$id)).'">Private candidate documents</a></p>';echo '</section>';
}
if($id){
 echo '<section class="panel"><h2>Internal notes</h2><form method="post">'.csrf_input().'<input type="hidden" name="action" value="note">';input_field('body','Add a private staff note','','textarea',true);echo '<button>Add note</button></form>';foreach(query('SELECT n.body,n.created_at,u.full_name FROM notes n JOIN admin_users u ON u.id=n.admin_user_id WHERE n.'.$m['note'].'=? ORDER BY n.id DESC LIMIT 100',[$id])->fetchAll() as $n)echo '<div class="note"><strong>'.e($n['full_name']).'</strong> · '.e($n['created_at']).' UTC<br>'.e($n['body']).'</div>';echo '</section><section class="panel"><h2>Status history</h2><ul>';foreach(query('SELECT h.*,u.full_name FROM status_history h LEFT JOIN admin_users u ON u.id=h.admin_user_id WHERE entity_type=? AND entity_id=? ORDER BY h.id DESC LIMIT 100',[$name,$id])->fetchAll() as $h)echo '<li>'.e($h['created_at']).' UTC · '.e($h['old_status']??'Created').' → '.e($h['new_status']).' · '.e($h['full_name']??'Website / system').'</li>';echo '</ul></section>';
}
